class Solution {
public:
    vector<int> pathInZigZagTree(int label) {
        vector<int> res;
        int curr = label;
        while (curr >= 1) {
            res.push_back(curr);
            int depth = 0;
            int temp = curr;
            while (temp > 0) {
                depth++;
                temp >>= 1;
            }
            int min_val = 1 << (depth - 1);
            int max_val = (1 << depth) - 1;
            curr = (min_val + max_val - curr) / 2;
        }
        reverse(res.begin(), res.end());
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> res = new ArrayList<>();
        int curr = label;
        while (curr >= 1) {
            res.add(curr);
            int depth = 32 - Integer.numberOfLeadingZeros(curr);
            int minVal = 1 << (depth - 1);
            int maxVal = (1 << depth) - 1;
            curr = (minVal + maxVal - curr) / 2;
        }
        Collections.reverse(res);
        return res;
    }
}

var pathInZigZagTree = function(label) {
    const res = [];
    let curr = label;
    while (curr >= 1) {
        res.push(curr);
        const depth = Math.floor(Math.log2(curr)) + 1;
        const minVal = 1 << (depth - 1);
        const maxVal = (1 << depth) - 1;
        curr = Math.floor((minVal + maxVal - curr) / 2);
    }
    return res.reverse();
};
